    knowledge: {
      combatAwareness: [
        { id: "mt-aw1", name: "Range System", description: "Understand kicking, punching, and clinch ranges (Muay Tae, Muay Mat, Muay Khao)." },
        { id: "mt-aw2", name: "Timing & Rhythm", description: "Attack on the off-beat of the opponent's bounce or inhale." },
        { id: "mt-aw3", name: "Targeting", description: "Prioritize liver, legs, jaw, and collarbone." },
        { id: "mt-aw4", name: "Distance Mgmt", description: "Use the teep to manage distance like a jab." },
        { id: "mt-aw5", name: "Angle Creation", description: "Step offline to remove counter-threats and open the flank." },
        { id: "mt-aw6", name: "Chamber Recog", description: "Spot shoulder dips or hip loads before strikes." },
        { id: "mt-aw7", name: "Balance Aware", description: "Attack when opponent's weight is on one leg or stepping." },
        { id: "mt-aw8", name: "Reaction Time", description: "Train visual cues to bypass conscious thought." },
        { id: "mt-aw9", name: "Spatial Orient", description: "Map ring ropes, corners, and boundaries before engagement." },
        { id: "mt-aw10", name: "Breath Sync", description: "Exhale sharply ('ish' or 'oosh') on every strike to brace the core." },
        { id: "mt-aw11", name: "Posture Ctrl", description: "Keep spine straight to transfer ground force and defend clinch." },
        { id: "mt-aw12", name: "Visual Focus", description: "Look at the chest/shoulders, not the hands or feet." },
        { id: "mt-aw13", name: "Momentum Read", description: "Redirect forward energy into sweeps or catches." },
        { id: "mt-aw14", name: "Range Trans", description: "Flow seamlessly from kick to punch to clinch." },
        { id: "mt-aw15", name: "Feint Recog", description: "Ignore false attacks, wait for commitment to check or counter." },
        { id: "mt-aw16", name: "Impact Assess", description: "Listen to the sound of the shin on the pad/body to gauge damage." },
        { id: "mt-aw17", name: "Recovery Aware", description: "Retract kicks faster than you extend them." },
        { id: "mt-aw18", name: "Environ Use", description: "Use ring corners to trap or escape depending on style." },
        { id: "mt-aw19", name: "Multi Threat", description: "Keep moving to prevent being surrounded (street context)." },
        { id: "mt-aw20", name: "Combat Pacing", description: "Explode, assess, then flow; manage the 5-round gas tank." }
      ],
      strategyTactics: [
        { id: "mt-st1", name: "Attrition Warfare", description: "Target the lead leg to destroy mobility over the rounds." },
        { id: "mt-st2", name: "Clinch Dominance", description: "Control the head to deliver knees and exhaust the opponent." },
        { id: "mt-st3", name: "Ring Generalship", description: "Control the center of the ring and force the opponent backward." },
        { id: "mt-st4", name: "Setup Kicks", description: "Use hand combinations to blind the opponent before throwing the heavy kick." },
        { id: "mt-st5", name: "Setup Punches", description: "Use heavy kicks to force a high guard, then punch the exposed body." },
        { id: "mt-st6", name: "Sabai Sabai", description: "Stay relaxed; tension wastes energy and slows down strikes." },
        { id: "mt-st7", name: "Counter-Kicking", description: "Wait for their kick, check it, and immediately return fire." },
        { id: "mt-st8", name: "Sweep Setups", description: "Use heavy pushes or strikes to hide the leg hook or trip." },
        { id: "mt-st9", name: "Corner Trapping", description: "Use lateral movement to pin the opponent against the ropes." },
        { id: "mt-st10", name: "Teep to Cross", description: "Push kick to the face to lift their chin, follow with a cross." },
        { id: "mt-st11", name: "Fake Teep", description: "Lift the lead leg to draw a reaction, then switch kick." },
        { id: "mt-st12", name: "Body Lock", description: "Switch from neck ties to body locks to drain their posture." },
        { id: "mt-st13", name: "Pace Breaking", description: "Change rhythm from slow stalking to explosive blitzes." },
        { id: "mt-st14", name: "Feinting", description: "Drop the shoulder to draw a check, then punch." },
        { id: "mt-st15", name: "Framing", description: "Use the long guard to keep aggressive Muay Khao (knee) fighters away." },
        { id: "mt-st16", name: "Energy Conservation", description: "Lean on the opponent in the clinch to make them carry your weight." },
        { id: "mt-st17", name: "Scoring Awareness", description: "Prioritize clean, visible damage and balance disruption over volume." },
        { id: "mt-st18", name: "Switch Kick Dominance", description: "Use the switch kick to bypass their lead leg check." },
        { id: "mt-st19", name: "Catch & Punish", description: "Catch kicks and sweep immediately to demoralize and score." },
        { id: "mt-st20", name: "Finish Strong", description: "Win the final round decisively to sway the judges' scorecards." }
      ],
      cultureEtiquette: [
        { id: "mt-cu1", name: "Wai Kru Ram Muay", description: "Traditional pre-fight dance to honor teachers, parents, and the sport." },
        { id: "mt-cu2", name: "Mongkhon", description: "Sacred headband worn during Wai Kru, removed before the fight begins." },
        { id: "mt-cu3", name: "Pra Jiad", description: "Armband worn for protection and luck, often blessed by monks." },
        { id: "mt-cu4", name: "Respect to Kru", description: "Bow to the instructor (Kru) and training partners." },
        { id: "mt-cu5", name: "Mat Etiquette", description: "Shoes off, no stepping on mats with street shoes." },
        { id: "mt-cu6", name: "Safety First", description: "Pull strikes to vital areas in training; control clinch throws." },
        { id: "mt-cu7", name: "Hygiene", description: "Trim nails, clean uniform, shower immediately to prevent staph/ringworm." },
        { id: "mt-cu8", name: "Punctuality", description: "Arrive early to prep the mats and warm up." },
        { id: "mt-cu9", name: "Humility", description: "Accept corrections without ego; you are always learning." },
        { id: "mt-cu10", name: "Discipline", description: "No talking during instruction; focus on the drill." },
        { id: "mt-cu11", name: "No Ego Sparring", description: "Protect lower belts from hard shots; flow light (Sabai Sabai)." },
        { id: "mt-cu12", name: "Lineage Respect", description: "Respect the Thai roots and the lineage of your gym." },
        { id: "mt-cu13", name: "Uniform", description: "Wear clean Muay Thai shorts and appropriate tops." },
        { id: "mt-cu14", name: "Mentorship", description: "Senior students (Nak Muay) guide juniors and hold pads safely." },
        { id: "mt-cu15", name: "Community", description: "Support gym events, seminars, and teammates' fights." },
        { id: "mt-cu16", name: "Integrity", description: "Do not use skills for bullying or outside the gym." },
        { id: "mt-cu17", name: "Perseverance", description: "Train through plateaus, fatigue, and minor injuries." },
        { id: "mt-cu18", name: "Self-Control", description: "Manage anger during sparring; it's a practice, not a street fight." },
        { id: "mt-cu19", name: "Cleaning Mats", description: "Help mop and sanitize the mats after every class." },
        { id: "mt-cu20", name: "Philosophy", description: "Embrace the spirit of the Nak Muay: respect, discipline, and heart." }
      ]
    },
